32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const basePremiumOf = (items: Item[]): number =>
55	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
56	
57	const quote = (step: QuoteStep): StepResult => {
58	  const basePremium = basePremiumOf(step.items);
59	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
60	
61	  return {
62	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
63	  };
64	};
65	
66	const runStep = (step: Step): StepResult => {
67	  switch (step.op) {
68	    case "quote":
69	      return quote(step);
70	    default:
71	      throw new Error(`Unsupported step: ${step.op}`);
72	  }
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResult => ({
76	  results: scenario.steps.map(runStep),
77	});
